/**
 * Which app ID the generated android/ project carries, against which one a build
 * is about to ask for.
 *
 * android/ is generated by prebuild and bakes in the variant (app.config.ts), so
 * a build for one variant run over a project generated for the other would ship
 * the wrong app — the very collision the variants exist to avoid.
 */

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));

/** The Android package Expo resolves for `variant`, read from the config itself so this file holds no copy of it. */
export function expectedVariantId(variant) {
  const result = spawnSync('pnpm', ['expo', 'config', '--json'], {
    cwd: ROOT,
    encoding: 'utf8',
    env: { ...process.env, APP_VARIANT: variant },
  });
  if (result.status !== 0) {
    throw new Error(`expo config failed for ${variant}:\n${result.stderr || result.stdout}`);
  }
  const json = result.stdout.split('\n').find((line) => line.startsWith('{'));
  const id = json && JSON.parse(json).android?.package;
  if (!id) throw new Error(`expo config for ${variant} has no android.package.`);
  return id;
}

/** The `applicationId` in the generated project, or null when there is none. */
export function generatedApplicationId(androidDir) {
  const gradle = join(androidDir, 'app/build.gradle');
  if (!existsSync(gradle)) return null;
  return /applicationId\s+['"]([^'"]+)['"]/.exec(readFileSync(gradle, 'utf8'))?.[1] ?? null;
}
